'use strict';
let storedPreferences={};try{storedPreferences=JSON.parse(localStorage.getItem('ieum-preferences')||'{}')}catch{}
window.gamePreferences={quality:storedPreferences.quality==='low'?'low':'balanced',ambient:storedPreferences.ambient!==false};
document.body.classList.add('game-layout');
const hud=document.createElement('button');hud.id='playerMenu';hud.className='player-menu';hud.setAttribute('aria-label','내 정보와 설정 열기');document.querySelector('header .wallet').before(hud);hud.onclick=openGameSettings;
const dayChip=document.createElement('div');dayChip.id='gameDay';dayChip.className='game-day';document.querySelector('header .wallet').before(dayChip);
const gear=document.createElement('button');gear.id='gameSettings';gear.className='settings-gear';gear.textContent='⚙';gear.setAttribute('aria-label','설정');gear.onclick=openGameSettings;document.querySelector('header').append(gear);
const objective=document.createElement('button');objective.className='game-objective';objective.id='gameObjective';scene.before(objective);objective.onclick=()=>gameNavigate('season');
const dock=document.createElement('nav');dock.className='game-dock';dock.setAttribute('aria-label','게임 메뉴');dock.innerHTML=[['farm','🌱','내 농장'],['village','🏡','마을'],['market','🛒','장터'],['bag','🎒','보관함'],['friends','👥','친구'],['settings','⚙','설정']].map(([id,icon,label])=>`<button data-game="${id}" aria-label="${label}"><span aria-hidden="true">${icon}</span><b>${label}</b></button>`).join('');document.body.append(dock);dock.addEventListener('click',e=>{const b=e.target.closest('[data-game]');if(b)gameNavigate(b.dataset.game)});
let gameWorkPanel=false;const workShortcut=document.createElement('button');workShortcut.id='openWork';workShortcut.textContent='🧑‍🌾 직업 활동';workShortcut.className='work-shortcut';document.querySelector('.view-switch').after(workShortcut);workShortcut.onclick=()=>{gameWorkPanel=true;tab='work';render();window.scrollTo({top:0,behavior:'instant'})};
const previousGameRender=render;render=function(){previousGameRender();updateGameUI()};
function updateGameUI(){const profileSave=document.querySelector('#saveNickname');if(profileSave){profileSave.disabled=window.classroomActive&&schoolPending;profileSave.textContent=profileSave.disabled?'저장 확인 중':'저장'}const j=state.job===null?null:jobs[state.job];hud.innerHTML=`<span class="player-portrait">${j?.icon||'🌱'}</span><span><b>${escapeHtml(state.name==='나'?'새싹 여행자':state.name)}</b><small>${j?.name||'직업을 골라 주세요'} · Lv.${state.level||1}</small></span><span class="profile-chevron">⌄</span>`;dayChip.innerHTML=`<b>${weather().icon} ${state.day}일째</b><small>${escapeHtml(weather().name)}</small>`;const count=window.classroomActive?classroomData.players?.length||0:0;objective.innerHTML=`<span class="objective-icon">✦</span><span><small>함께 만드는 마을 · ${window.classroomActive?count+'명의 이웃':'혼자 연습'}</small><b>${window.classroomActive&&classroomData.room.phase==='협력'?'우리 반 공동 식탁을 완성해요':'내 물건으로 이웃의 하루를 도와요'}</b></span><span class="objective-arrow">미션 보기 →</span>`;document.body.classList.toggle('activity-screen',tab!=='work'||gameWorkPanel);dock.querySelectorAll('[data-game]').forEach(b=>{const active=b.dataset.game===(tab==='market'?'market':tab==='season'?'':farmView?'farm':'village');b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')});document.querySelector('.world-heading h1').textContent=farmView?'나의 작은 농장':'모두의 일이 이어지는 마을';}
function gameNavigate(where){gameWorkPanel=false;if(where==='settings'){openGameSettings();return}if(where==='bag'){openGameBag();return}if(where==='friends'){openGameFriends();return}if($('#dialog').open)close();if(where==='farm'){setFarmView(true)}else{farmView=false;tab=where==='village'?'work':where;render()}updateGameUI();if(window.classroomActive&&!schoolPending)schoolAction({action:'place',place:where==='farm'?'work':where});if(innerWidth<761)window.scrollTo({top:0,behavior:'instant'})}
function openGameBag(){modal(`<div class="menu-heading"><span>MY STORAGE</span><button data-close aria-label="보관함 닫기">×</button></div><h2>내 보관함</h2><p>내가 만든 물건이 누군가에게 필요한 선물이 돼요.</p><div class="bag-grid">${jobs.map((j,i)=>`<div><span>${j.icon}</span><b>${items[i]}</b><strong>${state.stock[i]}<small>개</small></strong><em>오늘 시세 ${price(i)} 코인</em></div>`).join('')}</div><div class="account-row"><span>내 지갑</span><b>🪙 ${state.coins} 코인</b></div><div class="dialog-actions"><button data-close>계속 가꾸기</button><button class="primary" id="bagToMarket">장터로 가기 →</button></div>`);$('#bagToMarket').onclick=()=>gameNavigate('market')}
function openGameFriends(){const people=window.classroomActive?classroomData.players.filter(p=>p.id!==classroomData.me.id):[];modal(`<div class="menu-heading"><span>OUR NEIGHBORS</span><button data-close aria-label="친구 창 닫기">×</button></div><h2>우리 마을 이웃</h2><p>${window.classroomActive?`같은 학급의 친구 ${people.length}명 · 최근 접속 ${people.filter(p=>p.online).length}명`:'학급에 입장하면 실제 친구들을 만날 수 있어요.'}</p><label class="friend-search">친구 찾기<input id="friendSearch" placeholder="별명 또는 학생 번호" maxlength="30"></label><div class="friend-list" id="friendList"></div><button class="wide" data-close>마을로 돌아가기</button>`);const list=()=>{const query=$('#friendSearch').value.trim().toLowerCase();const shown=people.filter(p=>(p.name+' '+(p.accountName||'')).toLowerCase().includes(query));$('#friendList').innerHTML=shown.length?shown.map(p=>`<div class="friend-row"><span class="friend-avatar">${jobs[p.job].icon}</span><div><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.accountName||'')} · ${jobs[p.job].name}</small></div><span class="presence ${p.online?'online':''}">${p.online?'접속 중':'쉬는 중'}</span></div>`).join(''):'<div class="menu-empty">'+(people.length?'검색 결과가 없어요.':'아직 표시할 친구가 없어요. 학급 코드로 함께 입장해 주세요.')+'</div>'};$('#friendSearch').oninput=list;list()}
function openGameSettings(){const connected=window.classroomActive,room=connected?classroomData.room.code:'혼자 연습',account=connected?(classroomData.me.accountName||'학생 계정'):'이 브라우저의 연습 계정';modal(`<div class="menu-heading"><span>MY PAGE</span><button data-close aria-label="설정 닫기">×</button></div><h2>내 정보와 설정</h2><div class="settings-profile"><span>${jobs[state.job]?.icon||'🌱'}</span><div><b>${escapeHtml(state.name)}</b><small>${jobs[state.job]?.name||'아직 정하지 않았어요'} · 작업장 ${state.level}단계</small></div></div><form id="profileForm"><label for="nickname">마을에서 쓸 별명</label><div class="nickname-row"><input id="nickname" maxlength="12" required value="${escapeHtml(state.name)}" autocomplete="off"><button type="submit" class="primary" id="saveNickname">저장</button></div><small class="field-hint">실명 대신 별명을 사용해 주세요. 글자·숫자·공백 등 1~12자</small><p id="profileFeedback" role="status"></p></form><section class="settings-section"><h3>내 계정</h3><div class="account-row"><span>접속 방식</span><b>${connected?'학급 공동 플레이':'혼자 연습'}</b></div><div class="account-row"><span>학급 코드</span><b>${room}</b></div><div class="account-row"><span>학생 번호</span><b>${escapeHtml(account)}</b></div><div class="account-row"><span>저장 상태</span><b>${connected?(schoolPending?'저장 확인 중':schoolOnline?'서버에 저장됨':'연결 확인 필요'):'이 기기에 저장'}</b></div>${connected?'<div class="account-row"><span>내 입장 코드</span><button class="quiet" id="showOwnCode" type="button">확인하기</button></div><code class="own-code" id="ownCode" hidden></code><small class="field-hint">입장 코드는 내 계정의 열쇠예요. 다른 친구에게 알려주지 마세요.</small>':''}</section><section class="settings-section"><h3>화면 설정</h3><label class="account-row" for="qualitySetting"><span>그래픽 품질</span><select id="qualitySetting"><option value="balanced">기본</option><option value="low">가볍게 · 저사양 기기</option></select></label><label class="account-row" for="ambientSetting"><span>주민·나무의 배경 움직임</span><input type="checkbox" id="ambientSetting"></label><small class="field-hint">화면 설정은 지금 사용하는 기기에 저장됩니다.</small></section><div class="settings-links"><button id="settingsHelp">놀이 방법</button><button id="settingsRole">내 직업</button>${connected?'<button id="settingsRefresh">연결 새로 확인</button>':''}<a href="teacher.html">교사 운영실 ↗</a></div>${connected?'<button class="wide logout-button" id="settingsLogout">학급에서 나가기</button>':''}`);$('#profileForm').onsubmit=async e=>{e.preventDefault();const name=$('#nickname').value.trim();if(!/^[\p{L}\p{N} _.-]{1,12}$/u.test(name)){$('#profileFeedback').textContent='사용할 수 있는 글자와 길이를 확인해 주세요.';return}const button=$('#saveNickname');button.disabled=true;const ok=connected?await schoolAction({action:'profile',name}):(state.name=name,save(),render(),true);button.disabled=false;if(ok){$('#profileFeedback').textContent='별명을 저장했어요.';$('.settings-profile b').textContent=state.name}else $('#profileFeedback').textContent='저장하지 못했어요. 연결 또는 수업 상태를 확인해 주세요.'};$('#qualitySetting').value=gamePreferences.quality;$('#ambientSetting').checked=gamePreferences.ambient;updateGameUI();const preferences=()=>{gamePreferences.quality=$('#qualitySetting').value;gamePreferences.ambient=$('#ambientSetting').checked;localStorage.setItem('ieum-preferences',JSON.stringify(gamePreferences));window.dispatchEvent(new Event('village-preferences'))};$('#qualitySetting').onchange=preferences;$('#ambientSetting').onchange=preferences;$('#settingsHelp').onclick=()=>$('#help').click();$('#settingsRole').onclick=()=>$('#jobs').click();if(connected){$('#showOwnCode').onclick=()=>{const code=$('#ownCode');code.hidden=!code.hidden;code.textContent=code.hidden?'':schoolToken;$('#showOwnCode').textContent=code.hidden?'확인하기':'숨기기'};$('#settingsRefresh').onclick=async()=>{await refreshSchool();openGameSettings()};$('#settingsLogout').onclick=()=>{if(schoolPending||sessionStorage.getItem('village-pending-command')){toast('저장 확인 후 나가 주세요.');return}modal('<h2>학급에서 나갈까요?</h2><p>완료된 밭과 재고는 서버에 남아요. 같은 학급 코드와 내 입장 코드로 다시 들어올 수 있어요.</p><div class="dialog-actions"><button data-close>계속하기</button><button class="primary" id="confirmGameLogout">나가기</button></div>');$('#confirmGameLogout').onclick=()=>$('#reset').click()}}}
window.addEventListener('village-ready',updateGameUI);updateGameUI();
